From a151cc579021b026cb640c2b7789efa036226767 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:52:03 +0100
Subject: [PATCH] applets/minimizeall: share state with KWin's Minimize All
 script

The applet and KWin's Minimize All shortcut each remembered only the
windows they had minimized themselves, so one could not undo the other.
When that script is loaded, the applet now triggers it to toggle instead.

BUG: 420460
---
 applets/showdesktop/MinimizeAllController.qml | 66 +++++++++++++++++--
 1 file changed, 60 insertions(+), 6 deletions(-)

diff --git a/applets/showdesktop/MinimizeAllController.qml b/applets/showdesktop/MinimizeAllController.qml
index 1e35f0c72c..c4a8824de6 100644
--- a/applets/showdesktop/MinimizeAllController.qml
+++ b/applets/showdesktop/MinimizeAllController.qml
@@ -10,6 +10,7 @@
 import QtQml

 import org.kde.taskmanager as TaskManager
+import org.kde.plasma.workspace.dbus as DBus

 Controller {
     id: controller
@@ -20,7 +21,14 @@ Controller {
     descriptionActive: i18nc("@info:tooltip shown as subtitle", "Restores the previously minimized windows")
     descriptionInactive: i18nc("@info:tooltip shown as subtitle", "Shows the Desktop by minimizing all windows")

-    active: Boolean(activeByActivityDesktop[activityDesktopId])
+    active: kwinScriptLoaded ? visibleTasksModel.count === 0 && minimizedTasksModel.count > 0
+                             : Boolean(activeByActivityDesktop[activityDesktopId])
+
+    /**
+     * Whether KWin's Minimize All script is loaded. Its shortcut keeps its own
+     * list of minimized windows, so we go through it to share that list.
+     */
+    property bool kwinScriptLoaded: false

     readonly property QtObject virtualDesktopInfo: TaskManager.VirtualDesktopInfo {
         id: virtualDesktopInfo
@@ -36,6 +44,22 @@ Controller {
         groupMode: TaskManager.TasksModel.GroupDisabled
     }

+    readonly property QtObject visibleTasksModel: TaskManager.TasksModel {
+        groupMode: TaskManager.TasksModel.GroupDisabled
+        activity: activityInfo.currentActivity
+        filterByCurrentVirtualDesktop: true
+        filterByActivity: true
+        filterMinimized: true
+    }
+
+    readonly property QtObject minimizedTasksModel: TaskManager.TasksModel {
+        groupMode: TaskManager.TasksModel.GroupDisabled
+        activity: activityInfo.currentActivity
+        filterByCurrentVirtualDesktop: true
+        filterByActivity: true
+        filterNotMinimized: true
+    }
+
     readonly property string activityDesktopId: activityInfo.currentActivity + "_" + virtualDesktopInfo.currentDesktop

     readonly property var activeByActivityDesktop: ({})
@@ -113,12 +137,42 @@ Controller {
         }
     }

+    function updateKWinScriptLoaded(callback) {
+        DBus.SessionBus.asyncCall({
+            service: "org.kde.KWin",
+            path: "/Scripting",
+            iface: "org.kde.kwin.Scripting",
+            member: "isScriptLoaded",
+            arguments: [new DBus.string("minimizeall")],
+            signature: "(s)",
+        }, reply => {
+            kwinScriptLoaded = reply.value;
+            callback?.();
+        }, () => {
+            kwinScriptLoaded = false;
+            callback?.();
+        });
+    }
+
+    Component.onCompleted: updateKWinScriptLoaded()
+
     // override
     function toggle() {
-        if (active) {
-            deactivate();
-        } else {
-            activate();
-        }
+        updateKWinScriptLoaded(() => {
+            if (kwinScriptLoaded) {
+                DBus.SessionBus.asyncCall({
+                    service: "org.kde.kglobalaccel",
+                    path: "/component/kwin",
+                    iface: "org.kde.kglobalaccel.Component",
+                    member: "invokeShortcut",
+                    arguments: [new DBus.string("MinimizeAll")],
+                    signature: "(s)",
+                });
+            } else if (active) {
+                deactivate();
+            } else {
+                activate();
+            }
+        });
     }
 }
-- 
